      className: value.constructor?.name,
      keys: Object.getOwnPropertyNames(value).slice(0, 50),
      id: value.id,
      name: value.name,
      type: value.type
    };
  };
  return JSON.stringify({
    app: summarize(app),
    selection: summarize(app?.selection ?? app?.store?.selection)
  }, null, 2);
}"
```
